CREATE TABLE IF NOT EXISTS registry_sources (id text PRIMARY KEY, name text NOT NULL, sha256 text NOT NULL, researched_at date NOT NULL, notes text NOT NULL, source_document jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS registry_revision (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), version bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO registry_revision(singleton) VALUES(true) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS tools (id text PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, vendor text NOT NULL, description text NOT NULL, category text NOT NULL, website_url text, logo_url text, hosted_or_self_hosted text NOT NULL, integration_route text NOT NULL, status text NOT NULL CHECK(status IN ('discovery','supported')), api_support boolean, webhook_support boolean, business_models jsonb NOT NULL DEFAULT '[]', constraints text NOT NULL, integration_setup text NOT NULL, source_reference text NOT NULL, references_json jsonb NOT NULL, last_researched date NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS capabilities (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE IF NOT EXISTS tool_capabilities(tool_id text REFERENCES tools ON DELETE CASCADE, capability_id text REFERENCES capabilities, support_level text NOT NULL, notes text, PRIMARY KEY(tool_id,capability_id));
CREATE INDEX IF NOT EXISTS capability_candidates ON tool_capabilities(capability_id,tool_id);
CREATE TABLE IF NOT EXISTS tool_plans(id text PRIMARY KEY,tool_id text NOT NULL REFERENCES tools ON DELETE CASCADE,name text NOT NULL,currency text NOT NULL,billing_period text NOT NULL,base_price numeric CHECK(base_price>=0),pricing_type text NOT NULL,included_units jsonb NOT NULL,plan_requirements text NOT NULL,price_status text NOT NULL,price_text text NOT NULL,country text,production_eligible boolean,complete_price boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS plans_tool ON tool_plans(tool_id);
CREATE TABLE IF NOT EXISTS pricing_rules(id text PRIMARY KEY,tool_plan_id text NOT NULL REFERENCES tool_plans ON DELETE CASCADE,metric text NOT NULL,unit_price numeric,threshold numeric NOT NULL,formula_type text NOT NULL,metadata jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS tool_regions(tool_id text REFERENCES tools ON DELETE CASCADE,country text NOT NULL,supported boolean,notes text,PRIMARY KEY(tool_id,country));
CREATE TABLE IF NOT EXISTS tool_limits(id text PRIMARY KEY,tool_id text REFERENCES tools ON DELETE CASCADE,metric text NOT NULL,value numeric,plan_id text REFERENCES tool_plans,notes text NOT NULL);
CREATE TABLE IF NOT EXISTS tool_readiness(tool_id text PRIMARY KEY REFERENCES tools ON DELETE CASCADE,readiness_status text NOT NULL CHECK(readiness_status IN ('RESEARCHED','CONFIGURED','TESTED','SUPPORTED','RESTRICTED','RETIRED')),notes text NOT NULL);
CREATE TABLE IF NOT EXISTS tool_connections(id text PRIMARY KEY,tool_a_id text NOT NULL REFERENCES tools,tool_b_id text NOT NULL REFERENCES tools,connection_type text NOT NULL CHECK(connection_type IN ('native','middleware','configured_api','adapter','unsupported','unknown')),middleware_tool_id text REFERENCES tools,verified boolean NOT NULL,readiness_status text NOT NULL CHECK(readiness_status IN ('RESEARCHED','CONFIGURED','TESTED','SUPPORTED','RESTRICTED','RETIRED')),setup_complexity numeric,supported_direction text NOT NULL,notes text NOT NULL,last_verified_at timestamptz,source_reference text NOT NULL,authentication_method text,required_scopes jsonb,webhook_support boolean,polling_support boolean,rate_limits text,retry_behavior text,idempotency_support boolean,known_constraints jsonb NOT NULL,required_plan_ids jsonb NOT NULL DEFAULT '[]');
CREATE INDEX IF NOT EXISTS connection_neighbors_a ON tool_connections(tool_a_id);
CREATE INDEX IF NOT EXISTS connection_neighbors_b ON tool_connections(tool_b_id);
CREATE TABLE IF NOT EXISTS connection_operations(connection_id text REFERENCES tool_connections ON DELETE CASCADE,operation_name text NOT NULL,operation_type text NOT NULL,verified boolean NOT NULL,PRIMARY KEY(connection_id,operation_name));
CREATE TABLE IF NOT EXISTS stack_templates(template_id text PRIMARY KEY,name text NOT NULL,business_types jsonb NOT NULL,recommended_stack_pattern jsonb NOT NULL,tested_connections jsonb NOT NULL,confidence numeric NOT NULL,readiness_status text NOT NULL);
CREATE TABLE IF NOT EXISTS template_capabilities(template_id text REFERENCES stack_templates ON DELETE CASCADE,capability_id text REFERENCES capabilities,required boolean NOT NULL,PRIMARY KEY(template_id,capability_id));
CREATE TABLE IF NOT EXISTS template_tools(template_id text REFERENCES stack_templates ON DELETE CASCADE,tool_id text REFERENCES tools,PRIMARY KEY(template_id,tool_id));
CREATE TABLE IF NOT EXISTS confirmed_stacks(id uuid PRIMARY KEY,registry_version text NOT NULL,selection jsonb NOT NULL,pricing_snapshot jsonb NOT NULL,warnings jsonb NOT NULL,architecture_edges jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
-- Revisions cover all factual changes; confirmation uses one repeatable-read snapshot.
CREATE OR REPLACE FUNCTION bump_registry_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE registry_revision SET version=version+1,updated_at=now() WHERE singleton; RETURN NULL; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['registry_sources','tools','capabilities','tool_capabilities','tool_plans','pricing_rules','tool_regions','tool_limits','tool_readiness','tool_connections','connection_operations','stack_templates','template_capabilities','template_tools'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='revision_'||t) THEN EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH STATEMENT EXECUTE FUNCTION bump_registry_revision()', 'revision_'||t,t); END IF; END LOOP; END $$;
